CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, name text NOT NULL DEFAULT '', college text NOT NULL DEFAULT '', branch text NOT NULL DEFAULT '', year text NOT NULL DEFAULT '', bio text NOT NULL DEFAULT '', avatar_path text, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, UPDATE ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY profiles_read ON public.profiles FOR SELECT TO authenticated USING (true);
CREATE POLICY profiles_edit ON public.profiles FOR UPDATE TO authenticated USING (id=auth.uid()) WITH CHECK(id=auth.uid());
CREATE FUNCTION public.create_student_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(id,name) VALUES(NEW.id,coalesce(NEW.raw_user_meta_data->>'name','')); RETURN NEW; END; $$;
CREATE TRIGGER create_student_profile AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_student_profile();
CREATE TABLE public.skills (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, name text NOT NULL CHECK(length(trim(name))>0), kind text NOT NULL CHECK(kind IN ('teach','learn')), level text CHECK(level IN ('Beginner','Intermediate','Expert')), UNIQUE(user_id,name,kind));
GRANT SELECT, INSERT, DELETE ON public.skills TO authenticated; GRANT ALL ON public.skills TO service_role;
ALTER TABLE public.skills ENABLE ROW LEVEL SECURITY;
CREATE POLICY skills_read ON public.skills FOR SELECT TO authenticated USING(true);
CREATE POLICY skills_add ON public.skills FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid());
CREATE POLICY skills_remove ON public.skills FOR DELETE TO authenticated USING(user_id=auth.uid());
CREATE TABLE public.exchange_requests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), sender_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, recipient_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, teach_skill text NOT NULL, learn_skill text NOT NULL, message text NOT NULL DEFAULT '', status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','accepted','rejected')), created_at timestamptz NOT NULL DEFAULT now(), CHECK(sender_id<>recipient_id));
GRANT SELECT, INSERT, UPDATE ON public.exchange_requests TO authenticated; GRANT ALL ON public.exchange_requests TO service_role;
ALTER TABLE public.exchange_requests ENABLE ROW LEVEL SECURITY;
CREATE POLICY request_read ON public.exchange_requests FOR SELECT TO authenticated USING(auth.uid() IN(sender_id,recipient_id));
CREATE POLICY request_send ON public.exchange_requests FOR INSERT TO authenticated WITH CHECK(sender_id=auth.uid() AND status='pending' AND EXISTS(SELECT 1 FROM public.skills WHERE user_id=sender_id AND kind='teach' AND name=teach_skill) AND EXISTS(SELECT 1 FROM public.skills WHERE user_id=recipient_id AND kind='teach' AND name=learn_skill));
CREATE POLICY request_respond ON public.exchange_requests FOR UPDATE TO authenticated USING(recipient_id=auth.uid() AND status='pending') WITH CHECK(recipient_id=auth.uid() AND status IN('accepted','rejected'));
CREATE FUNCTION public.guard_request_update() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.sender_id IS DISTINCT FROM OLD.sender_id OR NEW.recipient_id IS DISTINCT FROM OLD.recipient_id OR NEW.teach_skill IS DISTINCT FROM OLD.teach_skill OR NEW.learn_skill IS DISTINCT FROM OLD.learn_skill OR NEW.message IS DISTINCT FROM OLD.message OR NEW.created_at IS DISTINCT FROM OLD.created_at OR NEW.id IS DISTINCT FROM OLD.id THEN RAISE EXCEPTION 'Only request status can change'; END IF; RETURN NEW; END; $$;
CREATE TRIGGER guard_request_update BEFORE UPDATE ON public.exchange_requests FOR EACH ROW EXECUTE FUNCTION public.guard_request_update();
CREATE TABLE public.messages(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), request_id uuid NOT NULL REFERENCES public.exchange_requests(id) ON DELETE CASCADE, sender_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, body text NOT NULL CHECK(length(trim(body)) BETWEEN 1 AND 4000), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT ON public.messages TO authenticated; GRANT ALL ON public.messages TO service_role;
ALTER TABLE public.messages ENABLE ROW LEVEL SECURITY;
CREATE POLICY messages_read ON public.messages FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.exchange_requests r WHERE r.id=request_id AND r.status='accepted' AND auth.uid() IN(r.sender_id,r.recipient_id)));
CREATE POLICY messages_send ON public.messages FOR INSERT TO authenticated WITH CHECK(sender_id=auth.uid() AND EXISTS(SELECT 1 FROM public.exchange_requests r WHERE r.id=request_id AND r.status='accepted' AND auth.uid() IN(r.sender_id,r.recipient_id)));
CREATE INDEX messages_request_time ON public.messages(request_id,created_at);
CREATE INDEX requests_recipient ON public.exchange_requests(recipient_id);
CREATE INDEX requests_sender ON public.exchange_requests(sender_id);
CREATE INDEX skills_user ON public.skills(user_id);
ALTER PUBLICATION supabase_realtime ADD TABLE public.messages;
ALTER PUBLICATION supabase_realtime ADD TABLE public.exchange_requests;
CREATE POLICY avatars_read ON storage.objects FOR SELECT TO authenticated USING(bucket_id='avatars');
CREATE POLICY avatars_add ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='avatars' AND (storage.foldername(name))[1]=auth.uid()::text);
CREATE POLICY avatars_edit ON storage.objects FOR UPDATE TO authenticated USING(bucket_id='avatars' AND (storage.foldername(name))[1]=auth.uid()::text) WITH CHECK(bucket_id='avatars' AND (storage.foldername(name))[1]=auth.uid()::text);
CREATE POLICY avatars_delete ON storage.objects FOR DELETE TO authenticated USING(bucket_id='avatars' AND (storage.foldername(name))[1]=auth.uid()::text);